mapper.select:
SELECT EXISTS(

    SELECT 1 FROM review_action WHERE owner_id=#{owner} AND id=#{id}
    SELECT 1 FROM memory_card WHERE owner_id=#{owner} AND id=#{id}
    SELECT 1 FROM preparation_task WHERE owner_id=#{owner} AND id=#{id}
    SELECT 1 WHERE FALSE

)



    SELECT id FROM memory_card WHERE owner_id=#{owner} AND status='ACTIVE'
      AND FALSE


    SELECT id FROM preparation_task WHERE owner_id=#{owner} AND status='TODO' AND planned_date IS NULL
      AND target_item_id=#{targetId} AND target_version_id=#{targetVersionId}

  SELECT id FROM preparation_task WHERE FALSE

AND id>#{after}
ORDER BY id ASC LIMIT #{limit}

SELECT u.target_id,u.target_version_id,u.requirement_id FROM growth_evidence_use u
JOIN preparation_item t ON t.owner_id=u.owner_id AND t.id=u.target_id AND t.kind='TARGET'
  AND t.status='ACTIVE' AND t.current_version_id=u.target_version_id
WHERE u.owner_id=#{owner} AND u.status='ACTIVE' AND u.coverage='INSUFFICIENT'
AND u.target_id=#{targetId} AND u.target_version_id=#{targetVersionId}

  AND (u.target_id>#{after.targetId}
    OR (u.target_id=#{after.targetId} AND u.target_version_id>#{after.targetVersionId})
    OR (u.target_id=#{after.targetId} AND u.target_version_id=#{after.targetVersionId} AND u.requirement_id>#{after.requirementId}))

GROUP BY u.target_id,u.target_version_id,u.requirement_id
ORDER BY u.target_id,u.target_version_id,u.requirement_id LIMIT #{limit}
